-- Create "not_found_paths" table
CREATE TABLE "not_found_paths" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "path_hash" character varying NOT NULL, "path" character varying NOT NULL, "hits" bigint NOT NULL DEFAULT 0, "first_seen" timestamptz NOT NULL, "last_seen" timestamptz NOT NULL, "referrer" character varying NOT NULL DEFAULT '', "ignored" boolean NOT NULL DEFAULT false, PRIMARY KEY ("id"));
-- Create index "not_found_paths_hash" to table: "not_found_paths"
CREATE UNIQUE INDEX "not_found_paths_hash" ON "not_found_paths" ("path_hash");
-- Create index "not_found_paths_ignored_hits" to table: "not_found_paths"
CREATE INDEX "not_found_paths_ignored_hits" ON "not_found_paths" ("ignored", "hits");
-- Create index "not_found_paths_last_seen" to table: "not_found_paths"
CREATE INDEX "not_found_paths_last_seen" ON "not_found_paths" ("last_seen");
-- Create "not_found_settings" table
CREATE TABLE "not_found_settings" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "keep_days" bigint NOT NULL DEFAULT 90, "show_count" boolean NOT NULL DEFAULT true, "ignore_patterns" text NOT NULL DEFAULT '', PRIMARY KEY ("id"));
